{
  "actions": [
    {
      "action": "Separate reservation requests from inspected-stock commitments",
      "mechanism": "Expected returns support tentative requests, not pickup promises; only inspected, uncommitted items support ready-for-pickup status.",
      "implementation": "Track each item's inspection, condition, accessories, and allocation. Atomically allocate inspected stock before confirming readiness; require consent before changing the reserved item.",
      "check": "Simulate concurrent reservations and late returns. No item receives overlapping commitments, and no uninspected item supports a readiness confirmation.",
      "risk": "Tentative status must be conspicuous during booking and afterward."
    },
    {
      "action": "Open recovery cases automatically when returns slip",
      "mechanism": "A missed return deadline creates owned, time-bounded recovery work for every dependent reservation.",
      "implementation": "Link reservations to expected returns. On lateness, create cases with an owner, pickup deadline, and branches for consented substitution, borrower-approved rescheduling, or recorded unfulfilled pickup.",
      "check": "Inject a late return affecting several bookings. Every affected booking gets a case; none closes without a recorded outcome.",
      "risk": "Notification alone must not count as completed recovery."
    },
    {
      "action": "Offer substitutions with explicit differences and consent",
      "mechanism": "Borrowers approve the actual replacement, including its condition and accessories, rather than a generic equivalence claim.",
      "implementation": "Offer inspected, uncommitted alternatives through the supplied contact preference. List differences, place an expiring hold, and record affirmative consent before allocation.",
      "check": "Test refusal, silence, expired holds, and changed accessories. None results in substitution without valid consent for the offered configuration.",
      "risk": "Long holds can obstruct recovery for other borrowers."
    },
    {
      "action": "Reserve operational time between return and pickup",
      "mechanism": "Scheduling gaps provide time for inspection and recovery without treating expected returns as inspected inventory.",
      "implementation": "Configure turnaround intervals from recorded inspection durations and opening hours. Reject impossible handoffs; label future-return-dependent requests tentative and retain their original requested pickup windows.",
      "check": "Replay actual timelines with proposed intervals. Report feasible handoffs, failed pickups, and requests displaced by the scheduling rule.",
      "risk": "Excessive gaps reduce access without necessarily preventing lateness."
    },
    {
      "action": "Prioritize inspections by threatened pickup deadlines",
      "mechanism": "Returned items blocking imminent reservations enter an urgent inspection queue, while safety requirements remain unchanged.",
      "implementation": "Keep returns unavailable pending inspection. Sort inspection work by dependent pickup deadline; use aging to prevent starvation and record condition and accessories before release.",
      "check": "Introduce an inspection backlog. Verify urgent items are surfaced, older work progresses, and incomplete or failed inspections never release stock.",
      "risk": "Deadline pressure must not shorten required safety checks."
    },
    {
      "action": "Check reservation conflicts before granting extensions",
      "mechanism": "Extension decisions expose downstream conflicts before an administrative change makes another reservation impossible.",
      "implementation": "Evaluate extension requests against dependent pickup windows and inspection time. Block automatic approval on conflict, preserve original deadlines, and open recovery work if continued possession threatens pickup.",
      "check": "Request an extension across a dependent booking. The system flags the conflict and never silently shifts that borrower's pickup.",
      "risk": "Declining an extension cannot ensure the item's physical return."
    },
    {
      "action": "Gate recovery communication by existing contact preferences",
      "mechanism": "A centralized dispatch rule prevents urgent recovery work from bypassing each borrower's permitted contact route.",
      "implementation": "Route reminders, substitution offers, and status changes only through the supplied preference. Record delivery failures; queue staff follow-up through that same route without collecting new contact details.",
      "check": "Test incompatible channels, failed delivery, and unanswered offers. No alternate-channel message or inferred consent occurs.",
      "risk": "An unreachable borrower may remain unrecovered before pickup."
    },
    {
      "action": "Measure failures against original booking intent",
      "mechanism": "Immutable booking cohorts prevent cancellations and rescheduling from disguising unsupported or missed pickup commitments.",
      "implementation": "Retain original windows and outcomes, including library-induced cancellations. Audit preventability against timestamped stock, inspection, consent, and recovery records; report tentative requests and confirmed pickups separately.",
      "check": "Cancel or move a difficult booking in test data. Its original-window miss remains counted; preventability requires evidence of a feasible timely intervention.",
      "risk": "Preventability judgments need documented rules and periodic review."
    }
  ],
  "abstention_reason": ""
}
